export type Plan = "free" | "pro";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
  plan: Plan;
  stripeCustomerId?: string;
  stripeSubscriptionId?: string;
};

// Kept on globalThis so route handlers and pages share one store in dev,
// where Next may bundle them as separate module instances.
const globalStore = globalThis as unknown as { __notelyUsers?: User[] };
const users: User[] = (globalStore.__notelyUsers ??= [
  { id: "1", email: "ada@example.com", name: "Ada", createdAt: "2026-01-04", plan: "free" },
  { id: "2", email: "grace@example.com", name: "Grace", createdAt: "2026-02-11", plan: "free" },
]);

export async function listUsers(): Promise<User[]> {
  return users;
}

export async function getUser(id: string): Promise<User | undefined> {
  return users.find((u) => u.id === id);
}

// TODO: there is no real session handling yet — the dashboard just picks the first user.
export async function getCurrentUser(): Promise<User | undefined> {
  return users[0];
}

export async function getUserByStripeCustomerId(customerId: string): Promise<User | undefined> {
  return users.find((u) => u.stripeCustomerId === customerId);
}

export async function updateUserBilling(
  id: string,
  patch: Partial<Pick<User, "plan" | "stripeCustomerId" | "stripeSubscriptionId">>,
): Promise<User | undefined> {
  const user = users.find((u) => u.id === id);
  if (user) Object.assign(user, patch);
  return user;
}
EOF
